// PPTalk-US Drizzle schema (Phase 0C)
//
// Conventions
// - All primary keys are UUIDv7 (Postgres `uuid` type). IDs are NOT generated by
//   the database; callers must pass an id from `uuidv7()` (npm: `uuidv7`) when
//   inserting. This keeps TS and Python ID generation consistent and gives us
//   sortable, distributed-safe IDs without a Postgres extension. Therefore no
//   `defaultRandom()` on `id` columns.
// - `created_at` / `updated_at` default to `now()` server-side. `updated_at` is
//   bumped by application code (no DB trigger yet).
// - `deleted_at` is null by default (soft delete) on every user-owned table.
// - `bigint` columns use `mode: 'number'` since the values we store
//   (e.g., video byte counts) fit comfortably within JS's safe integer range
//   (< 2^53). If we ever store values larger than that, switch to `'bigint'`.
// - Timestamps use `withTimezone: true, mode: 'date'`.

import {
  bigint,
  boolean,
  index,
  integer,
  jsonb,
  numeric,
  pgTable,
  real,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';
import type { InferInsertModel, InferSelectModel } from 'drizzle-orm';

// ---------- users ----------
export const users = pgTable('users', {
  id: uuid('id').primaryKey(),
  browserId: text('browser_id').notNull().unique(),
  email: text('email'),
  isSystem: boolean('is_system').notNull().default(false),
  createdAt: timestamp('created_at', { withTimezone: true, mode: 'date' }).notNull().defaultNow(),
  updatedAt: timestamp('updated_at', { withTimezone: true, mode: 'date' }).notNull().defaultNow(),
  deletedAt: timestamp('deleted_at', { withTimezone: true, mode: 'date' }),
});

// ---------- projects ----------
export const projects = pgTable(
  'projects',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id),
    name: text('name').notNull(),
    sourceKind: text('source_kind').notNull(), // 'pptx' | 'pdf'
    sourcePath: text('source_path').notNull(), // Supabase Storage key
    aspectW: integer('aspect_w'),
    aspectH: integer('aspect_h'),
    numSlides: integer('num_slides').notNull().default(0),
    status: text('status').notNull().default('parsing'), // parsing | ready | rendering | rendered | failed
    isSample: boolean('is_sample').notNull().default(false),
    createdAt: timestamp('created_at', { withTimezone: true, mode: 'date' }).notNull().defaultNow(),
    updatedAt: timestamp('updated_at', { withTimezone: true, mode: 'date' }).notNull().defaultNow(),
    deletedAt: timestamp('deleted_at', { withTimezone: true, mode: 'date' }),
  },
  (t) => ({
    userDeletedIdx: index('projects_user_deleted_idx').on(t.userId, t.deletedAt),
  }),
);

// ---------- slides ----------
export const slides = pgTable(
  'slides',
  {
    id: uuid('id').primaryKey(),
    projectId: uuid('project_id')
      .notNull()
      .references(() => projects.id, { onDelete: 'cascade' }),
    idx: integer('idx').notNull(), // current ordinal (0-indexed)
    originalIdx: integer('original_idx').notNull(),
    title: text('title'),
    bodyText: text('body_text'),
    speakerNotes: text('speaker_notes'),
    pngPath: text('png_path'),
    script: text('script'),
    scriptLocked: boolean('script_locked').notNull().default(false),
    audioPath: text('audio_path'),
    audioDurationS: real('audio_duration_s'),
    voice: text('voice'),
    createdAt: timestamp('created_at', { withTimezone: true, mode: 'date' }).notNull().defaultNow(),
    updatedAt: timestamp('updated_at', { withTimezone: true, mode: 'date' }).notNull().defaultNow(),
    deletedAt: timestamp('deleted_at', { withTimezone: true, mode: 'date' }),
  },
  (t) => ({
    projectIdxUnique: uniqueIndex('slides_project_idx_unique').on(t.projectId, t.idx),
  }),
);

// ---------- render_jobs ----------
export const renderJobs = pgTable(
  'render_jobs',
  {
    id: uuid('id').primaryKey(),
    projectId: uuid('project_id')
      .notNull()
      .references(() => projects.id, { onDelete: 'cascade' }),
    kind: text('kind').notNull(), // 'parse_only' | 'full_render' | 'slide_tts' | 'slide_script_regen'
    payload: jsonb('payload')
      .$type<Record<string, unknown>>()
      .notNull()
      .default({}),
    status: text('status').notNull().default('queued'), // queued | running | done | failed
    priority: integer('priority').notNull().default(0),
    claimedBy: text('claimed_by'),
    claimedAt: timestamp('claimed_at', { withTimezone: true, mode: 'date' }),
    startedAt: timestamp('started_at', { withTimezone: true, mode: 'date' }),
    completedAt: timestamp('completed_at', { withTimezone: true, mode: 'date' }),
    error: text('error'),
    attempts: integer('attempts').notNull().default(0),
    maxAttempts: integer('max_attempts').notNull().default(3),
    createdAt: timestamp('created_at', { withTimezone: true, mode: 'date' }).notNull().defaultNow(),
    updatedAt: timestamp('updated_at', { withTimezone: true, mode: 'date' }).notNull().defaultNow(),
  },
  (t) => ({
    // Supports `FOR UPDATE SKIP LOCKED` polling: filter by status,
    // order by priority desc then created_at asc.
    pollIdx: index('render_jobs_poll_idx').on(t.status, t.priority.desc(), t.createdAt),
  }),
);

// ---------- renders ----------
export const renders = pgTable('renders', {
  id: uuid('id').primaryKey(),
  projectId: uuid('project_id')
    .notNull()
    .references(() => projects.id, { onDelete: 'cascade' }),
  mp4Path: text('mp4_path').notNull(),
  srtPath: text('srt_path'),
  captions: boolean('captions').notNull().default(false),
  videoDurationS: real('video_duration_s'),
  videoBytes: bigint('video_bytes', { mode: 'number' }),
  costUsd: numeric('cost_usd', { precision: 12, scale: 6 }),
  createdAt: timestamp('created_at', { withTimezone: true, mode: 'date' }).notNull().defaultNow(),
});

// ---------- usage_events ----------
export const usageEvents = pgTable(
  'usage_events',
  {
    id: uuid('id').primaryKey(),
    projectId: uuid('project_id').references(() => projects.id),
    slideId: uuid('slide_id').references(() => slides.id),
    runId: text('run_id'),
    provider: text('provider').notNull(), // 'anthropic' | 'openai'
    model: text('model').notNull(),
    callType: text('call_type').notNull(),
    inputTokens: integer('input_tokens'),
    outputTokens: integer('output_tokens'),
    cacheCreationTokens: integer('cache_creation_tokens'),
    cacheReadTokens: integer('cache_read_tokens'),
    inputChars: integer('input_chars'),
    outputBytes: integer('output_bytes'),
    costUsd: numeric('cost_usd', { precision: 12, scale: 6 }).notNull(),
    durationSeconds: real('duration_seconds'),
    createdAt: timestamp('created_at', { withTimezone: true, mode: 'date' }).notNull().defaultNow(),
  },
  (t) => ({
    projectCreatedIdx: index('usage_events_project_created_idx').on(t.projectId, t.createdAt),
  }),
);

// ---------- inferred row / insert types ----------
export type User = InferSelectModel<typeof users>;
export type NewUser = InferInsertModel<typeof users>;

export type Project = InferSelectModel<typeof projects>;
export type NewProject = InferInsertModel<typeof projects>;

export type Slide = InferSelectModel<typeof slides>;
export type NewSlide = InferInsertModel<typeof slides>;

export type RenderJob = InferSelectModel<typeof renderJobs>;
export type NewRenderJob = InferInsertModel<typeof renderJobs>;

export type Render = InferSelectModel<typeof renders>;
export type NewRender = InferInsertModel<typeof renders>;

export type UsageEvent = InferSelectModel<typeof usageEvents>;
export type NewUsageEvent = InferInsertModel<typeof usageEvents>;
